export const ABILITY_PATCHES={"Feast":{"name":"Shared Pantry","text":"A consumed held healing Berry heals its holder normally and restores 1/8 max HP to one chosen living benched ally, once per battle. Berry regrowth cannot retrigger it."},"Floodplain":{"name":"Rain Sluice","text":"Once each battle, after surviving a damaging hit in rain, the next voluntary switch cures the incoming living ally\u2019s major status. No HP restoration; charge expires when rain ends."},"Marked Quarry":{"name":"Fortune Thread","text":"Double eligible optional secondary-effect chances, capped at 60% for the boosted result; never lower an existing chance above 60%. A 10% effect becomes 20%, 20% becomes 40%, 30% becomes 60%. One all-stat roll remains one roll. Does not change move accuracy, dedicated status moves, guaranteed effects, critical ratio, recoil, HP costs, item/ability triggers, Protect success or weather duration."},"Mimic Ear":{"name":"Countermelody","text":"After a damaging sound move hits the holder, its next sound move lowers the target\u2019s Sp. Attack one stage, once per switch-in. Trigger is consumed on a successful hit; does not boost damage."},"Palimpsest":{"name":"Margin Note","text":"After surviving the same opposing move twice while active, record it. The next voluntary replacement takes 30% less direct damage from that exact move once. Switching removes the holder\u2019s old record; no immunity or type-wide reduction."},"Sandcoat":{"name":"Sand Reservoir","text":"Immune to sand chip. After two complete active turns in sand, store one Silt charge. The next voluntary switch grants the incoming living ally a one-hit 20% physical-damage ward, then consumes the charge. One stored charge; wards do not stack."},"Weakpoint Hunter":{"name":"Native Force","text":"Increase the normal same-type attack bonus from \u00d71.5 to \u00d71.8. Check the user\u2019s current types; matching two types grants only one STAB bonus. Off-type attacks receive no benefit. No further multiplication after the replacement STAB value."},"Sage Mind":{"name":"Sage Mind","text":"Only SPECIAL damaging moves with at least one removable optional benefit gain \u00d71.3 base power; strip those tagged benefits. Retain recoil, HP costs, recharge, self-drops, accuracy checks and mandatory move rules. Moves without a removable benefit gain nothing. This replaces the current \u00d72 special-power rule and blanket effects removal."},"Reef Sentinel":{"name":"False Front","text":"The first direct damaging hit each battle is absorbed by a brittle shell. The user loses 1/8 max HP, respecting supervised HP floors. Only one hit is blocked; later multi-hit strikes connect. Does not block status or weather. Never resets by switching or healing."},"Mindwing":{"name":"Mindwing","text":"Special Flying moves ignore the target\u2019s positive Sp. Defence stages. Physical Flying moves remain Physical and gain no benefit. No category conversion."}};
