const stage=(stats,stages,target='SELF',chance_percent=100)=>e('stat_stage',{stats,stages,target,chance_percent});
const move=(id,name,type_id,category,power,pp,effects,rest={})=>({id,name,type_id,category,power,pp,effects,accuracy:100,priority:0,target:power?'SINGLE_FOE':'SELF',...rest});
