export function codexCompatible(s,id,data){const m=data.moves.find(m=>m.id===Number(id));if(!m)return false;if(id==700)return true;if(id==701)return s.base_stats.hp<=85;if(id==702)return s.base_stats.speed>=45||data.learnsets.some(l=>l.species_id===s.id&&data.moves.find(m=>m.id===l.move_id)?.category==='STATUS');return (m.tutorTypes||[]).some(t=>s.types.includes(t));}
export function installTeamcraft(data){if(data.teamcraftVersion)return;data.teamcraftVersion=1;
 for(const m of data.moves){m.contact??=m.category==='PHYSICAL'&&!/shot|arrow|projectile|launch|beam|wave|pulse/i.test(m.name);m.sound??=/roar|cry|call|chorus|song|chant|howl|chime|echo|shriek|resonance|sound|sonic/i.test(m.name);Object.assign(m,MOVE_PATCHES[m.id]||{});}
 const retired=data.moves.filter(m=>MOVE_ALIASES[m.id]);data.moves=data.moves.filter(m=>!MOVE_ALIASES[m.id]);for(const old of retired){const keep=data.moves.find(m=>m.id===canonicalMoveId(old.id));if(keep&&old.tutorTypes?.length)keep.tutorTypes=[...new Set([...(keep.tutorTypes||[]),...old.tutorTypes])];}
 const get=id=>data.moves.find(m=>m.id===id);
 for(const id of [11,96,97,352,353,549,556,479]){const m=get(id),fraction=id===11?[1,4]:id===353||id===549?[1,4]:id===556?[1,3]:id===479?[1,8]:[1,2];for(const ef of m.effects)if(['heal','party_heal'].includes(ef.effect_id))ef.max_hp_fraction=fraction;if(id===549)m.activeOnly=true;if(id===353){m.allyTarget=true;m.effects=[e('heal',{target:'PARTNER',max_hp_fraction:fraction})];}}
 for(const [id,effects]of [[387,[e('rain_mantle')]],[409,[e('single_ward',{category:'SPECIAL',turns:2,multiplier:.5})]],[417,[e('crit_guard',{turns:3})]],[441,[e('entry_cleanse')]],[455,[e('aurora_screen')]],[489,[e('ally_cure')]]]){get(id).effects=effects;if(id===489)get(id).allyTarget=true;}
 for(const [id,power,status,chance]of [[27,75,'BURN',30],[75,65,'PARALYSIS',30],[201,70,'CONFUSION',20]])get(id).effects=[e('inflict_status',{status,chance_percent:chance})];
 get(245).effects=[stage(combatStats,1,'SELF',10)];get(245).releaseMove=true;
 const mercy=get(470);Object.assign(mercy,{name:'Mercy Edge',adaptiveCategory:false,category:'PHYSICAL',effect_text:'Physical restraint strike. Direct damage leaves the target at 1 HP or more.'});data.moves.push({...mercy,id:710,name:'Mercy Ray',category:'SPECIAL',effect_text:'Special restraint ray. Direct damage leaves the target at 1 HP or more.'},...TEAMCRAFT_MOVES);
 const rows=[],seen=new Set();for(const l of data.learnsets){const m=get(canonicalMoveId(l.move_id));if(!m)continue;const k=l.species_id+':'+m.id;if(seen.has(k))continue;seen.add(k);rows.push({...l,move_id:m.id,name:m.name});}data.learnsets=rows;
 for(const s of data.species){s.ability_names={...SPECIES_ABILITY_SLOTS[s.id]||s.ability_names};s.abilities=Object.fromEntries(Object.entries(s.ability_names).map(([k,v])=>[k,'ABILITY_'+v.toUpperCase().replace(/[^A-Z0-9]+/g,'_')]));
 const ls=data.learnsets.filter(l=>l.species_id===s.id),offTypes=[...new Set(ls.map(l=>get(l.move_id)).filter(m=>m?.power&&!s.types.includes(m.type_id)&&!m.signature_owner_family).map(m=>m.type_id))];
 const keepTypes=new Set(offTypes.slice(0,2));let recovery=false;data.learnsets=data.learnsets.filter(l=>{if(l.species_id!==s.id)return true;const m=get(l.move_id);if(m.signature_owner_family)return true;if(m.power&&!s.types.includes(m.type_id)&&!keepTypes.has(m.type_id))return false;if(m.effects.some(e=>['heal','party_heal','heal_by_format'].includes(e.effect_id))){if(recovery)return false;recovery=true;}return true;});
 for(const m of TEAMCRAFT_MOVES.filter(m=>m.releaseMove&&s.types[0]===m.type_id&&s.id==='001'||m.releaseMove&&s.types[0]===m.type_id&&['FAMILY-001','FAMILY-004','FAMILY-007'].includes(s.family_id)))if(!data.learnsets.some(l=>l.species_id===s.id&&l.move_id===m.id))data.learnsets.push({species_id:s.id,move_id:m.id,name:m.name,level:28,method:'LEVEL_UP',teamcraft:true});
 }
 // Listed chance-based benefits are the only effects modified by the proc abilities.
 for(const m of data.moves)for(const ef of m.effects)if(m.power&&['inflict_status','flinch','stat_stage'].includes(ef.effect_id)&&ef.chance_percent>0&&ef.chance_percent<100&&!(ef.effect_id==='stat_stage'&&ef.target==='SELF'&&ef.stages<0))ef.secondary=true;
 for(const m of data.moves)m.effect_text=m.effect_text||'';
}
